import { Component, computed, effect, inject, signal } from '@angular/core';
import { PeopleService, Person } from '../people/people.service';

// The report: the unnamed sheet's ledger (the grand total of everyone's scaled, leaving out anyone
// whose scaled is "n/a"), its headcount and the mean (the ledger per person, rounded down), the same figures the worksheet shows. It reads them from
// the server itself and re-reads them whenever the people change.
@Component({
  selector: 'app-report',
  template: `
    <section aria-labelledby="report-title" data-testid="report">
      <h2 id="report-title">Report</h2>
      <p>Grand total: <strong data-testid="report-ledger">{{ ledger() }}</strong></p>
      <p>People: <strong data-testid="report-headcount">{{ headcount() }}</strong></p>
      <p>Average per person: <strong data-testid="report-mean">{{ mean() }}</strong></p>
    </section>
  `,
})
export class Report {
  private readonly service = inject(PeopleService);

  private readonly people = signal<Person[]>([]);
  protected readonly ledger = computed(() =>
    this.people().reduce((total, p) => total + (p.scaled ?? 0), 0),
  );
  protected readonly headcount = computed(() => this.people().length);
  protected readonly mean = computed(() =>
    this.headcount() === 0 ? 0 : Math.floor(this.ledger() / this.headcount()),
  );

  constructor() {
    effect(() => {
      this.service.revision();
      this.service.list(null).subscribe((people) => this.people.set(people));
    });
  }
}
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'people', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
  {
    path: 'people',
    data: { section: 'people', label: 'People', order: 1 },
    loadComponent: () => import('./features/people/people').then((m) => m.People),
  },
  {
    path: 'report',
    data: { section: 'report', label: 'Report', order: 2 },
    loadComponent: () => import('./features/report/report').then((m) => m.Report),
  },
];
import { Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NavigationEnd, Route, Router, RouterLink, RouterOutlet } from '@angular/router';
import { filter, map } from 'rxjs';
import { Report } from './features/report/report';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink, Report],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
      @if (!onReport()) {
        <aside data-testid="app-report">
          <app-report />
        </aside>
      }
    </div>
  `,
})
export class App {
  private readonly router = inject(Router);
  // The report shows beside every page except its own screen, where it is the page.
  protected readonly onReport = toSignal(
    this.router.events.pipe(
      filter((e) => e instanceof NavigationEnd),
      map((e) => e.urlAfterRedirects.split(/[?#]/)[0] === '/report'),
    ),
    { initialValue: false },
  );
  protected readonly nav: Route[] = this.router
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map } from 'rxjs';

// A person's workflow state, moved forward from DRAFT to REVIEW to FINAL; a FINAL person may be
// reopened to REWORK and moved forward to FINAL again.
export type State = 'DRAFT' | 'REVIEW' | 'FINAL' | 'REWORK';

export const STATES: readonly State[] = ['DRAFT', 'REVIEW', 'FINAL', 'REWORK'];

export interface Person {
  id: number;
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  delta: number | null;
  epsilon: number | null;
  zeta: number | null;
  grade: Grade | null;
  weight: number | null;
  kind: Kind | null;
  verge: number | null;
  thrust: number | null;
  drift: number | null;
  momentum: number | null;
  force: number | null;
  sway: number | null;
  torque: number | null;
  pivot: number | null;
  blend: number | null;
  flux: number | null;
  crest: number | null;
  swing: number | null;
  haul: number | null;
  vector: number | null;
  phase: string | null;
  load: number | null;
  tier: string | null;
  patrons: Patron[];
  backing: number | null;
  net: number | null;
  rank: number | null;
  percentile: number | null;
  quota: boolean;
  onset: string | null;
  age: number | null;
  decay: number | null;
  active: boolean;
  state: State;
  effective: number | null;
  clout: number | null;
  influence: number | null;
  brace: number | null;
  tide: number | null;
  strain: number | null;
  pulse: string | null;
  regions: string[];
  reach: number | null;
  gust: number | null;
  coil: number | null;
  allies: Ally[];
  allyCount: number;
  synergy: number | null;
  combined: number | null;
  score: number | null;
  noteSum: number;
  quality: number | null;
  adjusted: number | null;
  band: string | null;
  scaled: number | null;
  thrum: number | null;
  spool: number | null;
  drag: string | null;
  lift: number | null;
  yield: number | null;
  grip: number | null;
  charge: number | null;
  churn: number | null;
  flow: number | null;
  norm: number | null;
  outlier: boolean;
  // TOP when scaled is at or above the sheet's mean scaled, otherwise BOT; absent without a scaled.
  stratum: 'TOP' | 'BOT' | null;
  ebb: number | null;
  stray: boolean;
  // "Their group": the id and name of the group, of those they are in, whose name comes first
  // alphabetically; absent until put in one.
  groupId: number | null;
  groupName: string | null;
  // Every group the person is in, sorted by name.
  groups: Group[];
}

// A named group of people on a sheet.
export interface Group {
  id: number;
  name: string;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
  anchor: string;
}

export type Grade = 'LOW' | 'MID' | 'HIGH';

export const GRADES: readonly Grade[] = ['LOW', 'MID', 'HIGH'];

export type Kind = 'A' | 'B' | 'C';

export const KINDS: readonly Kind[] = ['A', 'B', 'C'];

export interface Patron {
  id: number;
  name: string;
}

// An ally: a person this person follows; following is one-directional.
export interface Ally {
  id: number;
  name: string;
}

export interface NewPerson {
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  delta: number | null;
  epsilon: number | null;
  zeta: number | null;
  grade: Grade | null;
  kind: Kind | null;
  regions: string[];
  groupId: number | null;
}

// The people REST API (/api/people).
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly changes = signal(0);

  // Bumped whenever the people have been (re)loaded, so views of them elsewhere can re-read theirs.
  readonly revision = this.changes.asReadonly();

  changed(): void {
    this.changes.update((n) => n + 1);
  }

  // The people on a sheet; null is the unnamed sheet.
  list(sheet: string | null): Observable<Person[]> {
    return this.http.get<Person[]>('/api/people', { params: sheetParams(sheet) });
  }

  // A sheet (with its anchor); null is the unnamed sheet.
  sheet(sheet: string | null): Observable<Sheet> {
    return this.http.get<Sheet>('/api/sheet', { params: sheetParams(sheet) });
  }

  // Opens a named sheet, starting a new empty one when no sheet has that id yet.
  openSheet(sheet: string): Observable<void> {
    return this.http.put(`/api/sheets/${encodeURIComponent(sheet)}`, null).pipe(map(() => undefined));
  }

  // The groups on a sheet; null is the unnamed sheet.
  groups(sheet: string | null): Observable<Group[]> {
    return this.http.get<Group[]>('/api/groups', { params: sheetParams(sheet) });
  }

  // Adds a named group to a sheet; null is the unnamed sheet.
  addGroup(sheet: string | null, name: string): Observable<Group> {
    return this.http.post<Group>('/api/groups', { name }, { params: sheetParams(sheet) });
  }

  // Puts a person in just one group by its id; null takes them out of every group.
  setGroup(sheet: string | null, id: number, groupId: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { groupId }, { params: sheetParams(sheet) });
  }

  // Puts a person in just the groups with these ids; none takes them out of every group.
  setGroups(sheet: string | null, id: number, groupIds: number[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { groupIds }, { params: sheetParams(sheet) });
  }

  // Adds a person to a sheet; null is the unnamed sheet.
  add(sheet: string | null, person: NewPerson): Observable<Person> {
    return this.http.post<Person>('/api/people', person, { params: sheetParams(sheet) });
  }

  // Updates the person with an id on a sheet (ids are per sheet); null is the unnamed sheet.
  update(sheet: string | null, id: number, values: Omit<NewPerson, 'name' | 'groupId'> & { groupId?: number | null }): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, values, { params: sheetParams(sheet) });
  }

  setAlpha(sheet: string | null, id: number, alpha: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { alpha }, { params: sheetParams(sheet) });
  }

  setBeta(sheet: string | null, id: number, beta: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { beta }, { params: sheetParams(sheet) });
  }

  setGamma(sheet: string | null, id: number, gamma: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { gamma }, { params: sheetParams(sheet) });
  }

  setDelta(sheet: string | null, id: number, delta: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { delta }, { params: sheetParams(sheet) });
  }

  setEpsilon(sheet: string | null, id: number, epsilon: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { epsilon }, { params: sheetParams(sheet) });
  }

  setZeta(sheet: string | null, id: number, zeta: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { zeta }, { params: sheetParams(sheet) });
  }

  setGrade(sheet: string | null, id: number, grade: Grade | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { grade }, { params: sheetParams(sheet) });
  }

  setKind(sheet: string | null, id: number, kind: Kind | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { kind }, { params: sheetParams(sheet) });
  }

  setRegions(sheet: string | null, id: number, regions: string[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { regions }, { params: sheetParams(sheet) });
  }

  setActive(sheet: string | null, id: number, active: boolean): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { active }, { params: sheetParams(sheet) });
  }

  // Moves a person forward to their next state (DRAFT -> REVIEW -> FINAL, REWORK -> FINAL).
  advance(sheet: string | null, id: number): Observable<Person> {
    return this.http.post<Person>(`/api/people/${id}/advance`, null, { params: sheetParams(sheet) });
  }

  // Reopens a FINAL person to REWORK.
  rework(sheet: string | null, id: number): Observable<Person> {
    return this.http.post<Person>(`/api/people/${id}/rework`, null, { params: sheetParams(sheet) });
  }

  // Moves a person back to their previous state (REVIEW -> DRAFT); refused once FINAL.
  demote(sheet: string | null, id: number): Observable<Person> {
    return this.http.post<Person>(`/api/people/${id}/demote`, null, { params: sheetParams(sheet) });
  }

  setPatrons(sheet: string | null, id: number, patronIds: number[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { patronIds }, { params: sheetParams(sheet) });
  }

  // Sets a person's whole-number score; null clears it.
  setScore(sheet: string | null, id: number, score: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { score }, { params: sheetParams(sheet) });
  }

  // Sets the people a person follows (their allies) by id; it does not make them follow back.
  setAllies(sheet: string | null, id: number, allyIds: number[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { allyIds }, { params: sheetParams(sheet) });
  }
}

function sheetParams(sheet: string | null): HttpParams {
  return sheet === null ? new HttpParams() : new HttpParams().set('sheet', sheet);
}
